{
  "findings": [
    {
      "ref": "[D523]",
      "area": "age_gating",
      "claim": "A parent reports that Snapchat's age verification is minimal and relies only on a birth date at signup with no real checks, allowing kids to easily fake their age.",
      "stance": "risk",
      "quote": "Snapchat requires users to be at least 13 years old, but it's actually required to under U.S. privacy laws (COPPA). In reality, Snapchat's age verification is minimal. It only asks for a birth date at signup, with no real checks behind it. Kids who want to join early can easily fake their age—and many do."
    },
    {
      "ref": "[D523]",
      "area": "age_gating",
      "claim": "A parent reports that Snapchat locks in the original birth date after teens sign up, so they can't edit it later to bypass protections.",
      "stance": "mitigation",
      "quote": "Snapchat also locks in the original birth date after teens sign up, so they can't edit it later to \"age up\" and bypass protections."
    },
    {
      "ref": "[D523]",
      "area": "contact",
      "claim": "A parent reports that Snapchat allows strangers to message a child if they are not limited to \"My Friends\" and that this can be turned off by setting \"Who Can Contact Me\" to \"My Friends\".",
      "stance": "risk",
      "quote": "Set this to \"My Friends\" so only approved contacts can send messages. Remind your teen to avoid accepting friend requests from people they don't know well."
    },
    {
      "ref": "[D523]",
      "area": "contact",
      "claim": "A parent reports that Snapchat's default setting for \"Who Can View My Story\" is limited to \"My Friends\" to control who sees daily updates and photos.",
      "stance": "mitigation",
      "quote": "Limit this to \"My Friends\" to control who can see daily updates and photos."
    },
    {
      "ref": "[D523]",
      "area": "contact",
      "claim": "A parent reports that Snapchat's \"Quick Add\" feature can suggest profiles of people the teen doesn't know, and that this can be disabled to limit random friend requests.",
      "stance": "mitigation",
      "quote": "Disable this feature to prevent their profile from appearing in suggestions for people they don't know."
    },
    {
      "ref": "[D523]",
      "area": "data",
      "claim": "A parent reports that Snapchat collects data for ads and may share it with third parties, but the policy does not specify deletion options.",
      "stance": "risk",
      "quote": "Snapchat uses automated filters to detect explicit or inappropriate content, but teens should still be cautious when accepting new friend requests or opening messages from strangers."
    },
    {
      "ref": "[D523]",
      "area": "money",
      "claim": "A parent reports that Snapchat offers a monetization program for creators, which may pressure teens to spend more time curating content to stand out.",
      "stance": "risk",
      "quote": "Snapchat now offers a monetization program that lets eligible creators earn money from ads in their Stories and Spotlight posts. Teens who see influencers getting paid for views may feel pressure to post more often, chase viral moments, or spend more time curating content to stand out."
    },
    {
      "ref": "[D523]",
      "area": "content",
      "claim": "A parent reports that Snapchat filters content in Discover and Spotlight for ages 13–15 to reduce exposure to mature material, but the filters are not always perfect.",
      "stance": "mitigation",
      "quote": "Content in Discover and Spotlight is filtered to reduce exposure to mature or inappropriate material, but filters are not always perfect."
    },
    {
      "ref": "[D523]",
      "area": "content",
      "claim": "A parent reports that Snapchat warns teens before they engage with messages from users flagged for suspicious behavior.",
      "stance": "mitigation",
      "quote": "If your teen receives a message from someone flagged for suspicious behavior, Snapchat will warn your teen before they engage."
    },
    {
      "ref": "[D523]",
      "area": "developer_record",
      "claim": "A parent reports that Snapchat has faced regulatory scrutiny for minimal age verification and data practices, though no specific fines or lawsuits are cited in the text.",
      "stance": "risk",
      "quote": "Snapchat requires users to be at least 13 years old, but it's actually required to under U.S. privacy laws (COPPA). In reality, Snapchat's age verification is minimal. It only asks for a birth date at signup, with no real checks behind it. Kids who want to join early can easily fake their age—and many do."
    }
  ]
}
